@extends('layouts.store') @section('title','Giỏ hàng | Sài Gòn CMC') @section('content')<div class="container-fluid container-wide"><div class="page-intro"><div class="breadcrumbs"><a href="{{ route('home') }}">Trang chủ</a> / Giỏ hàng</div><h1 class="page-title">Vật liệu bạn chọn</h1><p class="page-subtitle">Nhận tại kho với giá niêm yết, hoặc yêu cầu báo giá khi cần giao đến công trình.</p></div>@if($products->isEmpty())<div class="empty-state mb-5"><h2>Giỏ hàng đang trống</h2><a class="btn-editorial dark" href="{{ route('catalog') }}">Xem sản phẩm</a></div>@else<div class="row gx-4 gx-lg-5 gy-5 pb-5" data-cart-grid data-cart-catalog-url="{{ route('catalog') }}"><div class="col-lg-8">@foreach($products as $product)@php($fractional = in_array($product->unit, ['m³', 'kg'], true))<div class="cart-row"><span class="material-image {{ $product->image_path }}" role="img" aria-label="Ảnh minh họa {{ $product->name }}"></span><div><a href="{{ route('product',$product->id) }}"><h3>{{ $product->name }}</h3></a><p>{{ $product->specification }} · {{ number_format($product->price,0,',','.') }} ₫ / {{ $product->unit }}</p><p id="cartStockWarning{{ $product->id }}" class="cart-stock-warning" role="status" aria-live="polite" hidden></p><div class="cart-actions"><form class="cart-quantity-form" data-cart-update-form method="post" action="{{ route('cart.update') }}">@csrf<input type="hidden" name="product_id" value="{{ $product->id }}"><label for="qty{{ $product->id }}" class="visually-hidden">Số lượng {{ $product->name }}</label><div class="cart-stepper"><button type="submit" name="action" value="decrease" aria-label="Giảm số lượng {{ $product->name }}" @disabled((float) $cart[$product->id] <= ($fractional ? 0.001 : 1))>−</button><input id="qty{{ $product->id }}" type="number" name="quantity" data-cart-product-quantity="{{ $product->id }}" value="{{ $cart[$product->id] }}" min="{{ $fractional ? '0.001' : '1' }}" max="1000000" step="{{ $fractional ? '0.001' : '1' }}" required><button type="submit" name="action" value="increase" aria-label="Tăng số lượng {{ $product->name }}">+</button></div></form><form data-cart-update-form method="post" action="{{ route('cart.update') }}">@csrf<input type="hidden" name="product_id" value="{{ $product->id }}"><input type="hidden" name="quantity" value="0"><button class="cart-remove" type="submit" name="action" value="remove" aria-label="Xóa {{ $product->name }} khỏi giỏ">Xóa</button></form></div></div><strong class="cart-price">{{ number_format($product->price*$cart[$product->id],0,',','.') }} ₫</strong></div>@endforeach</div><div class="col-lg-4"><aside class="summary-card"><h2>Giỏ hàng của bạn</h2><div class="summary-line total"><span>Tổng giá niêm yết</span><strong>{{ number_format($total,0,',','.') }} ₫</strong></div><p class="demo-note">Giá đã gồm VAT. Nhận tại kho không tính phí giao.</p>@auth @if(auth()->user()->role==='customer')<section class="cart-checkout-option"><span class="eyebrow">Mua với giá niêm yết</span><h3>Nhận tại kho</h3><form id="pickupOrderForm" data-cart-submit method="post" action="{{ route('pickup-orders.store') }}">@csrf<input type="hidden" name="idempotency_key" value="{{ $pickupOrderKey }}" data-cart-key>@foreach($products as $checkoutProduct)<input type="hidden" name="quantities[{{ $checkoutProduct->id }}]" value="{{ $cart[$checkoutProduct->id] }}" data-checkout-quantity="{{ $checkoutProduct->id }}">@endforeach<label class="form-label" for="pickupWarehouse">Kho nhận hàng</label><select class="form-select" id="pickupWarehouse" name="warehouse_id" data-validation-message="Vui lòng chọn kho nhận hàng trước khi đặt hàng." required><option value="">Chọn kho</option>@foreach($warehouses as $warehouse)<option value="{{ $warehouse->id }}" @selected(old('warehouse_id') == $warehouse->id)>{{ $warehouse->name }}{{ $warehouse->address ? ' · '.$warehouse->address : '' }}</option>@endforeach</select><div id="pickupStockWarning" class="demo-note mt-2" role="status" aria-live="polite" hidden></div><button class="btn-editorial dark" type="submit" @disabled($warehouses->isEmpty() || !$canPickup)>Đặt hàng nhận tại kho</button></form>@if(!$canPickup)<p class="demo-note">Giỏ có vật liệu cần nhân viên xác nhận giá. Hãy gửi yêu cầu báo giá bên dưới.</p>@elseif($warehouses->isEmpty())<p class="demo-note">Chưa có kho nhận hàng. Bạn có thể gửi yêu cầu báo giá bên dưới.</p>@endif</section><section class="cart-checkout-option"><span class="eyebrow">Yêu cầu báo giá</span><h3>Báo giá vật liệu</h3><form method="post" data-cart-submit action="{{ route('quotes.request') }}">@csrf<input type="hidden" name="cart_key" value="{{ $pickupOrderKey }}" data-cart-key>@foreach($products as $quoteProduct)<input type="hidden" name="quantities[{{ $quoteProduct->id }}]" value="{{ $cart[$quoteProduct->id] }}" data-checkout-quantity="{{ $quoteProduct->id }}">@endforeach<label class="form-label" for="deliveryAddress">Địa chỉ công trình</label><textarea id="deliveryAddress" class="form-control" name="delivery_address" data-validation-message="Vui lòng nhập địa chỉ công trình." required>{{ old('delivery_address', auth()->user()->address) }}</textarea><label class="form-label mt-3" for="quoteNote">Ghi chú thêm (không bắt buộc)</label><textarea id="quoteNote" class="form-control" name="note">{{ old('note') }}</textarea><button class="btn-editorial cart-quote-button" type="submit">Yêu cầu báo giá công trình</button></form></section>@else<p class="demo-note">Tài khoản nhân viên không đặt hàng thay khách trên trang này.</p>@endif @else<a class="btn-editorial dark" href="{{ route('login') }}">Đăng nhập để tiếp tục</a>@endauth</aside></div></div>@endif</div><script>
document.addEventListener('DOMContentLoaded', () => {
    const select = document.getElementById('pickupWarehouse');
    const warning = document.getElementById('pickupStockWarning');
    if (!select || !warning) return;
    const availability = @json($availability);
    const products = @json($products->map(fn ($product) => ['id' => $product->id, 'name' => $product->name, 'unit' => $product->unit])->values());
    const formatQuantity = value => new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 3}).format(value);
    const update = () => {
        const stock = availability[select.value] || {};
        const warehouseName = select.selectedOptions[0]?.textContent.trim() || 'Kho đã chọn';
        const shortages = [];
        products.forEach((product) => {
            const requested = Number(document.getElementById(`qty${product.id}`)?.value || 0);
            const available = Number(stock[product.id] || 0);
            const hasShortage = Boolean(select.value) && requested > available;
            const lineWarning = document.getElementById(`cartStockWarning${product.id}`);
            if (lineWarning) {
                lineWarning.hidden = !hasShortage;
                lineWarning.textContent = hasShortage
                    ? `Kho ${warehouseName} còn ${formatQuantity(available)} ${product.unit}, yêu cầu ${formatQuantity(requested)} ${product.unit}. Kinh doanh sẽ kiểm tra và xác nhận thời gian bổ sung.`
                    : '';
            }
            if (hasShortage) shortages.push(product.name);
        });
        warning.hidden = !select.value || shortages.length === 0;
        warning.textContent = shortages.length
            ? `Kho chưa đủ tồn cho ${shortages.join(', ')}. Bạn vẫn có thể gửi đơn để Kinh doanh kiểm tra; thời gian bổ sung chưa được xác nhận.`
            : '';
    };
    select.addEventListener('change', update);
    document.querySelectorAll('.cart-stepper input[type="number"]').forEach((input) => input.addEventListener('input', update));
    update();
});
</script>@endsection
